  /**
   * Generates the shader string for the given type and value.
   *
   * @param {String} type - The type.
   * @param {Any?} [value=null] - The value.
   * @return {String} The generated value as a shader string.
   */
  generateConst(type) {
    let value = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : null;
    if (value === null) {
      if (type === 'float' || type === 'int' || type === 'uint') value = 0;else if (type === 'bool') value = false;else if (type === 'color') value = new Color();else if (type === 'vec2') value = new Vector2();else if (type === 'vec3') value = new Vector3();else if (type === 'vec4') value = new Vector4();
    }
    if (type === 'float') return toFloat(value);
    if (type === 'int') return "".concat(Math.round(value));
    if (type === 'uint') return value >= 0 ? "".concat(Math.round(value), "u") : '0u';
    if (type === 'bool') return value ? 'true' : 'false';
    if (type === 'color') return "".concat(this.getType('vec3'), "( ").concat(toFloat(value.r), ", ").concat(toFloat(value.g), ", ").concat(toFloat(value.b), " )");
    const typeLength = this.getTypeLength(type);
    const componentType = this.getComponentType(type);
    const generateConst = value => this.generateConst(componentType, value);
    if (typeLength === 2) {
      return "".concat(this.getType(type), "( ").concat(generateConst(value.x), ", ").concat(generateConst(value.y), " )");
    } else if (typeLength === 3) {
      return "".concat(this.getType(type), "( ").concat(generateConst(value.x), ", ").concat(generateConst(value.y), ", ").concat(generateConst(value.z), " )");
    } else if (typeLength === 4) {
      return "".concat(this.getType(type), "( ").concat(generateConst(value.x), ", ").concat(generateConst(value.y), ", ").concat(generateConst(value.z), ", ").concat(generateConst(value.w), " )");
    } else if (typeLength > 4 && value && (value.isMatrix3 || value.isMatrix4)) {
      return "".concat(this.getType(type), "( ").concat(value.elements.map(generateConst).join(', '), " )");
    } else if (typeLength > 4) {
      return "".concat(this.getType(type), "()");
    }
    throw new Error("NodeBuilder: Type '".concat(type, "' not found in generate constant attempt."));
  }

