  getDataFromNode(node) {
    let shaderStage = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : this.shaderStage;
    let cache = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : null;
    cache = cache === null ? node.isGlobal(this) ? this.globalCache : this.cache : cache;
    let nodeData = cache.getData(node);
    if (nodeData === undefined) {
      nodeData = {};
      cache.setData(node, nodeData);
    }
    if (nodeData[shaderStage] === undefined) nodeData[shaderStage] = {};
    return nodeData[shaderStage];
  }

  /**
   * Returns the properties for the given node and shader stage.
   *
   * @param {Node} node - The node to get the properties for.
   * @param {('vertex'|'fragment'|'compute'|'any')} [shaderStage='any'] - The shader stage.
   * @return {Object} The node properties.
   */
  getNodeProperties(node) {
    let shaderStage = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : 'any';
    const nodeData = this.getDataFromNode(node, shaderStage);
    return nodeData.properties || (nodeData.properties = {
      outputNode: null
    });
  }

  /**
   * Returns an instance of {@link NodeAttribute} for the given buffer attribute node.
   *
   * @param {BufferAttributeNode} node - The buffer attribute node.
   * @param {String} type - The node type.
   * @return {NodeAttribute} The node attribute.
   */
  getBufferAttributeFromNode(node, type) {
    const nodeData = this.getDataFromNode(node);
    let bufferAttribute = nodeData.bufferAttribute;
    if (bufferAttribute === undefined) {
      const index = this.uniforms.index++;
      bufferAttribute = new NodeAttribute('nodeAttribute' + index, type, node);
      this.bufferAttributes.push(bufferAttribute);
      nodeData.bufferAttribute = bufferAttribute;
    }
    return bufferAttribute;
  }

  /**
   * Returns an instance of {@link StructTypeNode} for the given output struct node.
   *
   * @param {OutputStructNode} node - The output struct node.
   * @param {Array<String>} types - The output struct types.
   * @param {('vertex'|'fragment'|'compute'|'any')} [shaderStage=this.shaderStage] - The shader stage.
   * @return {StructTypeNode} The struct type attribute.
   */
  getStructTypeFromNode(node, types) {
    let shaderStage = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : this.shaderStage;
    const nodeData = this.getDataFromNode(node, shaderStage);
    let structType = nodeData.structType;
    if (structType === undefined) {
      const index = this.structs.index++;
      structType = new StructTypeNode('StructType' + index, types);
      this.structs[shaderStage].push(structType);
      nodeData.structType = structType;
    }
    return structType;
  }

  /**
   * Returns an instance of {@link NodeUniform} for the given uniform node.
   *
   * @param {UniformNode} node - The uniform node.
   * @param {String} type - The uniform type.
   * @param {('vertex'|'fragment'|'compute'|'any')} [shaderStage=this.shaderStage] - The shader stage.
   * @param {String?} name - The name of the uniform.
   * @return {NodeUniform} The node uniform.
   */
  getUniformFromNode(node, type) {
    let shaderStage = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : this.shaderStage;
    let name = arguments.length > 3 && arguments[3] !== undefined ? arguments[3] : null;
    const nodeData = this.getDataFromNode(node, shaderStage, this.globalCache);
    let nodeUniform = nodeData.uniform;
    if (nodeUniform === undefined) {
      const index = this.uniforms.index++;
      nodeUniform = new NodeUniform(name || 'nodeUniform' + index, type, node);
      this.uniforms[shaderStage].push(nodeUniform);
      nodeData.uniform = nodeUniform;
    }
    return nodeUniform;
  }

  /**
   * Returns an instance of {@link NodeVar} for the given variable node.
   *
   * @param {VarNode} node - The variable node.
   * @param {String?} name - The variable's name.
   * @param {String} [type=node.getNodeType( this )] - The variable's type.
   * @param {('vertex'|'fragment'|'compute'|'any')} [shaderStage=this.shaderStage] - The shader stage.
   * @return {NodeVar} The node variable.
   */
  getVarFromNode(node) {
    let name = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : null;
    let type = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : node.getNodeType(this);
    let shaderStage = arguments.length > 3 && arguments[3] !== undefined ? arguments[3] : this.shaderStage;
    const nodeData = this.getDataFromNode(node, shaderStage);
    let nodeVar = nodeData.variable;
    if (nodeVar === undefined) {
      const vars = this.vars[shaderStage] || (this.vars[shaderStage] = []);
      if (name === null) name = 'nodeVar' + vars.length;
      nodeVar = new NodeVar(name, type);
      vars.push(nodeVar);
      nodeData.variable = nodeVar;
    }
    return nodeVar;
  }

  /**
   * Returns an instance of {@link NodeVarying} for the given varying node.
   *
   * @param {(VaryingNode|PropertyNode)} node - The varying node.
   * @param {String?} name - The varying's name.
   * @param {String} [type=node.getNodeType( this )] - The varying's type.
   * @return {NodeVar} The node varying.
   */
  getVaryingFromNode(node) {
    let name = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : null;
    let type = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : node.getNodeType(this);
    const nodeData = this.getDataFromNode(node, 'any');
    let nodeVarying = nodeData.varying;
    if (nodeVarying === undefined) {
      const varyings = this.varyings;
      const index = varyings.length;
      if (name === null) name = 'nodeVarying' + index;
      nodeVarying = new NodeVarying(name, type);
      varyings.push(nodeVarying);
      nodeData.varying = nodeVarying;
    }
    return nodeVarying;
