    let output = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : null;
    let propertyName = arguments.length > 3 && arguments[3] !== undefined ? arguments[3] : null;
    const previousShaderStage = this.shaderStage;
    this.setShaderStage(shaderStage);
    const flowData = this.flowChildNode(node, output);
    if (propertyName !== null) {
      flowData.code += "".concat(this.tab + propertyName, " = ").concat(flowData.result, ";\n");
    }
    this.flowCode[shaderStage] = this.flowCode[shaderStage] + flowData.code;
    this.setShaderStage(previousShaderStage);
    return flowData;
  }

  /**
   * Returns an array holding all node attributes of this node builder.
